<?php $error='';if($_SERVER['REQUEST_METHOD']==='POST')try{if($role!=='examinee')throw new RuntimeException('Student admission history is read-only.');if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['booking_csrf'],$_POST['csrf']))throw new RuntimeException('Reload before cancelling.');$portal->cancel((int)$uid,(int)($_POST['cancel_exam']??0));$_SESSION['success_message']='Your exam booking was cancelled. A notification has been saved.';header('Location: layout.php?page=view_application');exit;}catch(Throwable $e){$error=$e instanceof PDOException?'The application could not be updated.':$e->getMessage();}$message=$_SESSION['success_message']??'';unset($_SESSION['success_message']);?>
<section class="ex-workspace"><header class="ex-heading"><div><p class="ex-eyebrow">Your entrance examination</p><h1>My application</h1><p class="ex-muted">Your current schedule and previous applications, all in one place.</p></div><a class="ex-button primary" href="layout.php?page=book_exam">Open exam calendar</a></header><?php if($message):?><p class="ex-alert" role="status"><?=$exE($message)?></p><?php endif;?><?php if($error):?><p class="ex-alert error" role="alert"><?=$exE($error)?></p><?php endif;?>
