<?php foreach($apps as $i=>$app):?><article class="ex-card ex-application"><header class="ex-application-head"><div><p class="ex-eyebrow"><?=$i===0?'Latest application':'Previous application'?></p><h2><?=$exE(date('F j, Y',strtotime($app['preferred_date'])))?> · <?=$exE(date('g:i A',strtotime($app['preferred_time'])))?></h2><p class="ex-muted">Submitted <?=$exE(date('M j, Y',strtotime($app['created_at'])))?></p></div><span class="ex-status <?=$exE(!empty($app['rescheduled_to_id'])?'rescheduled':(!empty($app['reschedule_pending'])?'pending':$app['status']))?>"><?=$exE(!empty($app['rescheduled_to_id'])?'Unfinished · Rescheduled':(!empty($app['reschedule_pending'])?'Awaiting a new schedule':ExamineePortal::label($app['status'])))?></span></header><p><?=$exE(!empty($app['rescheduled_to_id'])?'This unfinished attempt is kept in your history. Your replacement exam schedule appears above.':(!empty($app['reschedule_pending'])?'No open future exam session is currently available. Your application will move automatically when an available session is published.':(!empty($app['rescheduled_from_id'])?'This is your replacement schedule for an unfinished exam. Please attend at the scheduled time.':ExamineePortal::description($app['status']))))?></p><dl class="ex-details"><div><dt>Applying for</dt><dd><?=$exE($app['grade_level_applying'])?></dd></div><div><dt>Previous school</dt><dd><?=$exE($app['previous_school']?:'Not provided')?></dd></div><div><dt>Preferred program</dt><dd><?=$exE($app['preferred_program']?:'Not provided')?></dd></div></dl><div class="ex-actions"><?php if($app['status']==='completed'):?><a class="ex-button primary" href="layout.php?page=view_exam_results">View released results</a><?php endif;?><?php if($role==='examinee'&&in_array($app['status'],['pending','confirmed'],true)&&$app['preferred_date']>=date('Y-m-d')):?><details><summary class="ex-button danger">Cancel this booking</summary><p>Cancel only if you will not attend this examination.</p><form method="post"><input type="hidden" name="csrf" value="<?=$exE($_SESSION['booking_csrf'])?>"><button class="ex-button danger" name="cancel_exam" value="<?=(int)$app['id']?>">Confirm cancellation</button></form></details><?php endif;?></div></article><?php endforeach;?></section>
